sed -i 's/CREATE POLICY "Mindenki elérheti" ON works FOR ALL USING (true) WITH CHECK (true);/CREATE POLICY "Mindenki elérheti" ON works FOR ALL USING (true) WITH CHECK (true);\n\n-- 10. APP_SETTINGS (Beállítások)\nCREATE TABLE IF NOT EXISTS app_settings (\n    id TEXT PRIMARY KEY,\n    settings_json JSONB NOT NULL,\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE app_settings ENABLE ROW LEVEL SECURITY;\nDROP POLICY IF EXISTS "Mindenki elérheti" ON app_settings;\nCREATE POLICY "Mindenki elérheti" ON app_settings FOR ALL USING (true) WITH CHECK (true);/' js/app.js
